   611  static void parse_if_modified_since(struct lwan_request_parser_helper *helper)
   612  {
   613      static const size_t header_len =
   614          sizeof("Wed, 17 Apr 2019 13:59:27 GMT") - 1;
   615      time_t parsed;
   616
   617      if (UNLIKELY(helper->if_modified_since.raw.len != header_len))
   618          return;
   619
   620      if (UNLIKELY(lwan_parse_rfc_time(helper->if_modified_since.raw.value,
   621                                       &parsed) < 0))
   622          return;
   623
   624      helper->if_modified_since.parsed = parsed;
