   627  static void
   628  parse_range(struct lwan_request_parser_helper *helper)
   629  {
   630      if (UNLIKELY(helper->range.raw.len <= (sizeof("bytes=") - 1)))
   631          return;
   632
   633      char *range = helper->range.raw.value;
   634      if (UNLIKELY(strncmp(range, "bytes=", sizeof("bytes=") - 1)))
   635          return;
   636
   637      range += sizeof("bytes=") - 1;
   638      uint64_t from, to;
   639
   640      if (sscanf(range, "%"SCNu64"-%"SCNu64, &from, &to) == 2) {
   641          if (UNLIKELY(from > OFF_MAX || to > OFF_MAX))
   642              goto invalid_range;
   643
   644          helper->range.from = (off_t)from;
   645          helper->range.to = (off_t)to;
   646      } else if (sscanf(range, "-%"SCNu64, &to) == 1) {
   647          if (UNLIKELY(to > OFF_MAX))
   648              goto invalid_range;
   649
   650          helper->range.from = 0;
   650          helper->range.from = 0;
   651          helper->range.to = (off_t)to;
   652      } else if (sscanf(range, "%"SCNu64"-", &from) == 1) {
   653          if (UNLIKELY(from > OFF_MAX))
   654              goto invalid_range;
   655
   656          helper->range.from = (off_t)from;
   657          helper->range.to = -1;
   658      } else {
   659  invalid_range:
   660          helper->range.from = -1;
   661          helper->range.to = -1;
   662      }
   663  }
