   665  static void
   666  parse_accept_encoding(struct lwan_request *request)
   667  {
   668      struct lwan_request_parser_helper *helper = request->helper;
   669
   670      if (!helper->accept_encoding.len)
   671          return;
   672
   673      for (const char *p = helper->accept_encoding.value; *p; p++) {
   674          STRING_SWITCH(p) {
   675          case MULTICHAR_CONSTANT('d','e','f','l'):
   676          case MULTICHAR_CONSTANT(' ','d','e','f'):
   677              request->flags |= REQUEST_ACCEPT_DEFLATE;
   678              break;
   679          case MULTICHAR_CONSTANT('g','z','i','p'):
   680          case MULTICHAR_CONSTANT(' ','g','z','i'):
   681              request->flags |= REQUEST_ACCEPT_GZIP;
   682              break;
   683          }
   684
   685          if (!(p = strchr(p, ',')))
   686              break;
   687      }
   688  }
