   698  static ALWAYS_INLINE void parse_connection_header(struct lwan_request *request)
   699  {
   700      struct lwan_request_parser_helper *helper = request->helper;
   701      bool has_keep_alive = false;
   702      bool has_close = false;
   703
   704      if (!helper->connection.len)
   705          goto out;
   706
   707      for (const char *p = helper->connection.value; *p; p++) {
   708          STRING_SWITCH_L(p) {
   709          case MULTICHAR_CONSTANT_L('k','e','e','p'):
   710          case MULTICHAR_CONSTANT_L(' ', 'k','e','e'):
   711              has_keep_alive = true;
   712              break;
   713          case MULTICHAR_CONSTANT_L('c','l','o','s'):
   714          case MULTICHAR_CONSTANT_L(' ', 'c','l','o'):
   715              has_close = true;
   716              break;
   717          case MULTICHAR_CONSTANT_L('u','p','g','r'):
   718          case MULTICHAR_CONSTANT_L(' ', 'u','p','g'):
   719              request->conn->flags |= CONN_IS_UPGRADE;
   720              break;
   721          }
   722
   723          if (!(p = strchr(p, ',')))
   724              break;
   725      }
   726
   727  out:
   728      if (LIKELY(!(request->flags & REQUEST_IS_HTTP_1_0)))
   729          has_keep_alive = !has_close;
   730
   731      if (has_keep_alive)
   732          request->conn->flags |= CONN_KEEP_ALIVE;
   733      else
   734          request->conn->flags &= ~CONN_KEEP_ALIVE;
   735  }
